#!/usr/bin/env python3
"""Generate icons – python3 src-tauri/icons/generate_icons.py"""
import base64
from pathlib import Path
OUT = Path(__file__).parent
FILES = {
  "32x32.png": "",
  "128x128.png": "",
}
for name, b64 in FILES.items():
    (OUT / name).write_bytes(base64.b64decode(b64))
    print("wrote", name)
print("Icons ready.")
